def shopping_menu(prefix=''):
    types=''.join(f'<a href="{prefix}{path}/">{t.TYPE_NAMES[key]}</a>' for key,path in t.TYPE_PATHS.items())
    brands=''.join(f'<a href="{prefix}index.html?q={quote(name)}#inventory">{t.E(name)}</a>' for name in ['American Coach','Brinkley','Coachmen','Dynamax','Entegra Coach','Fleetwood','Forest River','Newmar','Thor Motor Coach','Tiffin','Winnebago'])
    return f'''<details class="shop-menu"><summary>Shop RVs <span aria-hidden="true">⌄</span></summary><div class="shop-menu-panel"><div><h3>Find your starting point</h3><a href="{prefix}index.html#inventory">All RVs</a><a href="{prefix}new-rvs-for-sale/">New RVs</a><a href="{prefix}used-rvs-for-sale/">Pre-owned RVs</a><a href="{prefix}index.html?deal=1#inventory">Deals of the Week</a><a href="{prefix}index.html#budget">Shop by budget</a><a href="{prefix}compare.html">Compare RVs</a></div><div><h3>By RV type</h3>{types}</div><div><h3>By brand</h3>{brands}</div></div></details>'''

